    kur_expertise_h2: { tr:"Tek çatı altında yönetilen dört ana hizmet başlığı.", en:"Four main service areas managed under one roof.", de:"Vier Hauptleistungsbereiche unter einem Dach.", fr:"Quatre principaux domaines de services gérés sous un même toit.", it:"Quattro principali aree di servizio gestite sotto un unico tetto.", es:"Cuatro áreas de servicio principales gestionadas bajo un mismo techo.", ar:"أربعة مجالات خدمة رئيسية تُدار تحت سقف واحد.", ru:"Четыре основных направления услуг под одной крышей." },
    kur_card1_num: { tr:"İnşaat", en:"Construction", de:"Bau", fr:"Construction", it:"Costruzione", es:"Construcción", ar:"الإنشاء", ru:"Строительство" },
    kur_card1_h: { tr:"Uygulama ve Taahhüt", en:"Implementation and Contracting", de:"Ausführung und Auftrag", fr:"Réalisation et Entreprise", it:"Realizzazione e Appalto", es:"Ejecución y Contratación", ar:"التنفيذ والمقاولة", ru:"Реализация и подряд" },
    kur_card1_p: { tr:"Saha kurulumu, şantiye yönetimi ve kontrollü yapım süreçleri. Temel kazısından geçici kabulüne tek muhatap.", en:"Site setup, construction site management and controlled building processes. A single point of contact from excavation to provisional acceptance.", de:"Baustelleneinrichtung, Baustellenmanagement und kontrollierte Bauprozesse. Ein Ansprechpartner vom Aushub bis zur vorläufigen Abnahme.", fr:"Installation de chantier, gestion de chantier et processus de construction maîtrisés. Un interlocuteur unique de l'excavation à la réception provisoire.", it:"Allestimento del cantiere, gestione del cantiere e processi costruttivi controllati. Un unico referente dallo scavo al collaudo provvisorio.", es:"Instalación de obra, gestión de obra y procesos de construcción controlados. Un único interlocutor desde la excavación hasta la recepción provisional.", ar:"تجهيز الموقع وإدارة الورشة وعمليات بناء محكومة. جهة اتصال واحدة من الحفر حتى الاستلام المؤقت.", ru:"Организация площадки, управление стройплощадкой и контролируемые процессы строительства. Единый контакт от выемки грунта до предварительной приёмки." },
    kur_card2_num: { tr:"Mimarlık", en:"Architecture", de:"Architektur", fr:"Architecture", it:"Architettura", es:"Arquitectura", ar:"العمارة", ru:"Архитектура" },
    kur_card2_h: { tr:"Tasarım ve Proje Dili", en:"Design and Project Language", de:"Entwurf und Projektsprache", fr:"Conception et Langage de Projet", it:"Design e Linguaggio di Progetto", es:"Diseño y Lenguaje de Proyecto", ar:"التصميم ولغة المشروع", ru:"Дизайн и язык проекта" },
    kur_card2_p: { tr:"Konsept geliştirme, uygulama projesi, cephe tasarımı ve teknik detay yönetimi. İç mekândan kentsel ölçeğe.", en:"Concept development, construction drawings, façade design and technical detail management. From interiors to urban scale.", de:"Konzeptentwicklung, Ausführungsplanung, Fassadengestaltung und Detailmanagement. Vom Innenraum bis zum städtischen Maßstab.", fr:"Développement de concept, projet d'exécution, conception de façade et gestion des détails techniques. De l'intérieur à l'échelle urbaine.", it:"Sviluppo del concept, progetto esecutivo, design della facciata e gestione dei dettagli tecnici. Dagli interni alla scala urbana.", es:"Desarrollo de concepto, proyecto de ejecución, diseño de fachada y gestión de detalles técnicos. Del interior a la escala urbana.", ar:"تطوير المفهوم ومشروع التنفيذ وتصميم الواجهات وإدارة التفاصيل التقنية. من الفراغات الداخلية إلى المقياس الحضري.", ru:"Разработка концепции, рабочая документация, дизайн фасадов и управление техническими деталями. От интерьеров до городского масштаба." },
    kur_card3_num: { tr:"Çelik Sistem", en:"Steel System", de:"Stahlsystem", fr:"Système Acier", it:"Sistema Acciaio", es:"Sistema de Acero", ar:"النظام الفولاذي", ru:"Стальная система" },
    kur_card3_h: { tr:"Hafif Çelik Çözümleri", en:"Light Steel Solutions", de:"Leichtstahllösungen", fr:"Solutions en Acier Léger", it:"Soluzioni in Acciaio Leggero", es:"Soluciones de Acero Ligero", ar:"حلول الفولاذ الخفيف", ru:"Решения из лёгкой стали" },
    kur_card3_p: { tr:"Villa, tek katlı yaşam yapısı ve özel planlı hafif çelik sistem uygulamaları. Hızlı kurulum ve uzun ömür.", en:"Villas, single-storey living structures and custom-planned light steel system applications. Fast assembly and long service life.", de:"Villen, eingeschossige Wohngebäude und individuell geplante Leichtstahlanwendungen. Schnelle Montage und lange Lebensdauer.", fr:"Villas, structures de vie de plain-pied et applications de systèmes en acier léger sur mesure. Montage rapide et grande longévité.", it:"Ville, strutture abitative a un piano e applicazioni di sistemi in acciaio leggero su misura. Montaggio rapido e lunga durata.", es:"Villas, estructuras de vivienda de una planta y aplicaciones de sistema de acero ligero a medida. Montaje rápido y larga vida útil.", ar:"فلل ومبانٍ سكنية من طابق واحد وتطبيقات أنظمة فولاذ خفيف مخصصة. تركيب سريع وعمر طويل.", ru:"Виллы, одноэтажные жилые здания и индивидуальные решения из лёгкой стали. Быстрый монтаж и долгий срок службы." },
    kur_stats_eyebrow: { tr:"Sayılarla Aşkın Yapı", en:"Aşkın Yapı in Numbers", de:"Aşkın Yapı in Zahlen", fr:"Aşkın Yapı en Chiffres", it:"Aşkın Yapı in Numeri", es:"Aşkın Yapı en Cifras", ar:"أشكين يابي بالأرقام", ru:"Aşkın Yapı в цифрах" },
    kur_stats_h2: { tr:"14 yıllık birikim, belgelenmiş referanslar.", en:"14 years of accumulated experience, documented references.", de:"14 Jahre Erfahrung, dokumentierte Referenzen.", fr:"14 ans d'expérience accumulée, des références documentées.", it:"14 anni di esperienza accumulata, referenze documentate.", es:"14 años de experiencia acumulada, referencias documentadas.", ar:"خبرة متراكمة على مدى 14 عاماً ومراجع موثقة.", ru:"14 лет накопленного опыта, документированные референсы." },
    kur_metric1: { tr:"Kuruluş yılı ve ilk referans projesi", en:"Year of foundation and first reference project", de:"Gründungsjahr und erstes Referenzprojekt", fr:"Année de création et premier projet de référence", it:"Anno di fondazione e primo progetto di referenza", es:"Año de fundación y primer proyecto de referencia", ar:"سنة التأسيس وأول مشروع مرجعي", ru:"Год основания и первый референсный проект" },
